{
  "architect_scope": "one-R91-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "The active family settles evidence through an early executable artifact, leaving later calls constrained by that artifact's path dependence and by partial evidence reentry.",
    "causal_change": "Place a binding pre-artifact authority cut between full-context interpretation and policy creation: the first call emits only an obligation charter, and a source-blind terminal call creates the sole executable policy.",
    "expected_effect": "Settling obligations before executable form exists should change both scan-resistance behavior and phase-shift adaptation behavior while making object-versus-byte objective balancing less dependent on inherited artifact form.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "pre-artifact authority cut with source-blind terminal materialization",
    "before": "Immediate executable creation followed by disjoint raw-evidence reentries that mutate the inherited complete artifact.",
    "after": "One full-context policy-free charter becomes the sole edge into a terminal materializer; raw evidence has no downstream edge, and executable state begins only at the final call.",
    "why_structural": "The single authority cut removes reentry edges, changes evidence timing from post-artifact repair to pre-artifact settlement, and relocates executable-state creation to one terminal transition."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "An executable artifact must exist before evidence authority can be settled.",
      "Disjoint downstream evidence reentry is necessary to reconcile obligations.",
      "Continuous custody of a mutable executable artifact is safer than policy-free precommitment."
    ],
    "forbidden_inherited_mechanism": "progressive mutation of one complete executable artifact across disjoint downstream evidence-window reentries",
    "independent_replacement_principle": "bind all source evidence once into a policy-free obligation charter, then permit exactly one source-blind transition that creates the policy",
    "changed_behavioral_dimensions": [
      "scan-resistance behavior",
      "phase-shift adaptation behavior",
      "object-versus-byte objective balancing"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Pre-Artifact Constitutional Cut",
    "organization": "two-call sequential lineage with full-context policy-free authority followed by source-blind sole policy materialization",
    "information_flow": "The first call receives every common input and emits an authoritative non-policy obligation charter. The final call consumes only that immediately preceding charter, receives no reopened common input, creates the lineage's first executable artifact, and emits one policy.",
    "stages": [
      {
        "id": "constitutional_cut_lineage",
        "mode": "sequential",
        "calls": [
          {
            "id": "constitute_policy_free_charter",
            "role": "full-context obligation authority",
            "objective": "Interpret the six visible inputs jointly and emit an authoritative policy-free analysis of obligations, conflicts, and acceptance boundaries without creating an executable artifact.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "analysis"
          },
          {
            "id": "materialize_from_charter",
            "role": "source-blind sole policy authority",
            "objective": "Consume constitute_policy_free_charter as the sole visible evidence, realize its settled obligations in one complete policy, and emit that policy without reopening source evidence.",
            "inputs": [
              "constitute_policy_free_charter"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "materialize_from_charter"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
